// One API for the UI. Inside the Tauri app it calls Rust; in a plain browser
// (design work, screenshots) it serves fixtures generated by the real engine.

import type { DeviceSpecs, Mode, Plan, Platform, Recipe, Review, Verdict } from "./types";

const inTauri = typeof window !== "undefined" && "__TAURI_INTERNALS__" in window;

async function call<T>(cmd: string, args?: Record<string, unknown>): Promise<T> {
  const { invoke } = await import("@tauri-apps/api/core");
  return invoke<T>(cmd, args);
}

const wait = (ms: number) => new Promise((r) => setTimeout(r, ms));

export const api = {
  inTauri,

  platform(): Promise<Platform> {
    return inTauri ? call("platform") : Promise.resolve({ canScan: false, os: "browser" });
  },

  async scan(demo: boolean): Promise<Recipe> {
    if (inTauri) return call("scan", { demo });
    await wait(2400);
    return (await import("./mock/recipe.json")).default as unknown as Recipe;
  },

  async demoTarget(): Promise<DeviceSpecs> {
    if (inTauri) return call("demo_target");
    return (await import("./mock/target.json")).default as unknown as DeviceSpecs;
  },

  async review(recipe: Recipe, mode: Mode, target: DeviceSpecs | null, organizeFiles = false): Promise<Review> {
    if (inTauri) return call("review", { recipe, mode, target, options: { organizeFiles } });
    await wait(350);
    const fixtures = {
      newDevice: () => import("./mock/review-newDevice.json"),
      "newDevice-organized": () => import("./mock/review-newDevice-organized.json"),
      refreshThisPc: () => import("./mock/review-refreshThisPc.json"),
      "refreshThisPc-organized": () => import("./mock/review-refreshThisPc-organized.json"),
    } as const;
    const key = (organizeFiles ? `${mode}-organized` : mode) as keyof typeof fixtures;
    return (await fixtures[key]()).default as unknown as Review;
  },

  async checkPlan(recipe: Recipe, plan: Plan): Promise<Verdict> {
    if (inTauri) return call("check_plan", { recipe, plan });
    await wait(400);
    return (await import("./mock/bad-plan.json")).default.verdict as unknown as Verdict;
  },

  async badPlanExample(): Promise<Plan> {
    return (await import("./mock/bad-plan.json")).default.plan as unknown as Plan;
  },

  /** The only external link the app opens (allowed in capabilities/default.json). */
  donateUrl: "https://www.pcrf.net/donate/gazareliefandrecovery.html",

  async openDonate(): Promise<void> {
    if (inTauri) {
      const { openUrl } = await import("@tauri-apps/plugin-opener");
      await openUrl(api.donateUrl);
    } else {
      window.open(api.donateUrl, "_blank", "noopener,noreferrer");
    }
  },

  async saveRecipe(recipe: Recipe): Promise<string | null> {
    if (inTauri) return call("save_recipe", { recipe });
    return null;
  },
};
